CREATE TABLE users (id CHAR(36) PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, status VARCHAR(32) NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE roles (id CHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions (id CHAR(36) PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id CHAR(36) NOT NULL, role_id CHAR(36) NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE role_permissions (role_id CHAR(36) NOT NULL, permission_id CHAR(36) NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE content_items (id CHAR(36) PRIMARY KEY, slug VARCHAR(180) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, content_type VARCHAR(80) NOT NULL, lifecycle_state VARCHAR(32) NOT NULL DEFAULT 'draft', published_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_content_state_pub(lifecycle_state,published_at));
CREATE TABLE content_revisions (id CHAR(36) PRIMARY KEY, content_item_id CHAR(36) NOT NULL, revision_no INT NOT NULL, author_id CHAR(36) NULL, content_json JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_content_revision(content_item_id,revision_no), FOREIGN KEY(content_item_id) REFERENCES content_items(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE media_assets (id CHAR(36) PRIMARY KEY, filename VARCHAR(255) NOT NULL, media_type VARCHAR(120) NOT NULL, storage_reference VARCHAR(500) NOT NULL, lifecycle_state VARCHAR(32) NOT NULL DEFAULT 'active', size_bytes BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_media_state_type(lifecycle_state,media_type));
CREATE TABLE enquiries (id CHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(255) NOT NULL, company VARCHAR(255) NULL, message TEXT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'new', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_enquiries_status_created(status,created_at));
CREATE TABLE career_opportunities (id CHAR(36) PRIMARY KEY, slug VARCHAR(180) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, lifecycle_state VARCHAR(32) NOT NULL DEFAULT 'draft', published_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_career_state_pub(lifecycle_state,published_at));
CREATE TABLE audit_events (id CHAR(36) PRIMARY KEY, actor_id CHAR(36) NULL, action VARCHAR(120) NOT NULL, target_type VARCHAR(100) NULL, target_id CHAR(36) NULL, outcome VARCHAR(32) NOT NULL, request_id VARCHAR(64) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_actor_time(actor_id,created_at), INDEX idx_audit_target_time(target_type,target_id,created_at));